import{_ as t,o,c as d,a2 as c}from"./chunks/framework.DFu8lfqj.js";const h=JSON.parse('{"title":"主要特性","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features.md","filePath":"guide/features.md"}'),a={name:"guide/features.md"};function r(i,e,l,s,u,p){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="主要特性" tabindex="-1">主要特性 <a class="header-anchor" href="#主要特性" aria-label="Permalink to &quot;主要特性&quot;">​</a></h1><p>README 用六个小节描述了 BirdAdmin 的核心特性。本章保留原文要点，并补充当前仓库中可以核对的细节。</p><table tabindex="0"><thead><tr><th>特性</th><th>一句话概括</th><th>当前可核对的实现</th></tr></thead><tbody><tr><td>👍 流行稳定的技术栈</td><td>主流方案，生态成熟</td><td>Vue 3.5 / Vite 7 / TS 5.8 / Element Plus 2.10 / Pinia 3</td></tr><tr><td>🔀 前后端分离</td><td>纯前端仓库，独立部署</td><td><code>.env*</code> 中的 <code>VITE_API_URL</code> 与 <code>/api</code> 代理</td></tr><tr><td>✨ 高颜值</td><td>三种布局，无边框设计</td><td><code>layout/</code>、主题与尺寸配置</td></tr><tr><td>🔐 权限验证</td><td>可视化、动态注册、无限层级</td><td>路由白名单、<code>import.meta.glob</code> 自动注册</td></tr><tr><td>📝 未来可期</td><td>持续维护，模块化扩展</td><td>基础设施模块规划中</td></tr><tr><td>💖 其他杂项</td><td>配置 / 控制台 / 个人资料</td><td>设置 store、控制台输出、登录页</td></tr></tbody></table><h2 id="👍-流行且稳定的技术栈" tabindex="-1">👍 流行且稳定的技术栈 <a class="header-anchor" href="#👍-流行且稳定的技术栈" aria-label="Permalink to &quot;👍 流行且稳定的技术栈&quot;">​</a></h2><blockquote><p>除了基于 <code>Node.js</code> 前后端分离架构外，我们的 <code>Vue3</code> 使用了 <code>setup、useTemplateRef</code> 等，状态管理使用 <code>Pinia</code>，并使用了 <code>TypeScript、Vite</code> 等可以为你的知识面添砖加瓦的技术栈。使用流行技术栈自然代表本框架兼容相关（Vue3+Nodejs+Koa2）生态，生态系统内数不清的库、包、组件，能够使您的开发事半功倍。</p></blockquote><p>选型全部落在主流生态内：Vue 3 组合式 API（<code>setup</code>、<code>useTemplateRef</code>）、Pinia 状态管理、TypeScript 类型约束、Vite 构建、Element Plus 组件库，再配合 UnoCSS、VueUse、Axios 等工具。</p><p>好处是遇到问题几乎都能在社区找到答案，团队接手成本低。完整版本清单见<a href="/bird-admin-docs/guide/tech-stack.html">技术栈与依赖</a>。</p><h2 id="🔀-前后端分离" tabindex="-1">🔀 前后端分离 <a class="header-anchor" href="#🔀-前后端分离" aria-label="Permalink to &quot;🔀 前后端分离&quot;">​</a></h2><blockquote><p>项目的 <code>web</code> 文件夹内包含：<code>干净</code>（不含后端代码）、<code>完整</code>（所有前端代码文件均在此内）的前端代码文件，代码和部署均可前后分离，对前端开发者友好。作为纯前端开发者，您可以将 BAdmin 当做学习与资源的社群，本系统可为您准备好案例和模板等所需要的环境，而您只需专注于学习或工作，不需要会任何后端代码！</p></blockquote><p>当前仓库就是一份不含后端代码的前端工程：接口地址通过 <code>VITE_API_URL</code> 配置，开发服务器提供 <code>/api</code> 代理，本地还能用 <code>mock/</code> 下的假数据独立调试登录流程。</p><div class="tip custom-block"><p class="custom-block-title">关于 README 中的 <code>web</code> 文件夹</p><p>当前 Gitee 仓库根目录下并没有 <code>web</code> 目录，前端代码直接位于 <code>src/</code>。阅读旧版说明时请以<a href="/bird-admin-docs/guide/project-structure.html">目录结构</a>为准。</p></div><h2 id="✨-高颜值" tabindex="-1">✨ 高颜值 <a class="header-anchor" href="#✨-高颜值" aria-label="Permalink to &quot;✨ 高颜值&quot;">​</a></h2><blockquote><p>提供三种布局模式，其中默认布局使用无边框设计风格，它并没有强行填满屏幕的每一个缝然后使用边框线进行分隔，所有的功能版块，都像是悬浮在屏幕上的，同时又将屏幕空间及其合理的利用了。</p></blockquote><p>界面层由 <code>layout/</code> 承载，并提供深浅色主题（默认跟随操作系统 <code>prefers-color-scheme</code>）、组件尺寸、语言与水印等设置项，统一由 <code>store/modules/settings.ts</code> 与 <code>config/index.ts</code> 管理。</p><h2 id="🔐-权限验证" tabindex="-1">🔐 权限验证 <a class="header-anchor" href="#🔐-权限验证" aria-label="Permalink to &quot;🔐 权限验证&quot;">​</a></h2><blockquote><p>可视化的管理权限，然后根据权限动态的注册路由、菜单、页面、按钮（权限节点）、支持无限父子级权限分组、前后端搭配鉴权，自由分派页面和按钮权限。</p></blockquote><p>这是 BirdAdmin 最被强调的能力：菜单与按钮不再写死，而是由权限数据动态生成，前后端配合完成鉴权。</p><p>当前仓库里可以直接看到的基础设施包括：</p><ul><li><code>router/index.ts</code> 使用 <code>import.meta.glob</code> 自动收集 <code>router/modules/**/*.ts</code>，无需手动引入路由模块；</li><li>使用 <code>createWebHashHistory()</code> 的 hash 路由，部署到静态托管更省心；</li><li>路由前置守卫 <code>router.beforeEach</code> 与白名单 <code>[&quot;/login&quot;]</code>，用于登录态校验；</li><li><code>utils/auth.ts</code> 提供认证相关工具函数。</li></ul><p>更多细节见<a href="/bird-admin-docs/guide/routing.html">路由与权限</a>。</p><h2 id="📝-未来可期" tabindex="-1">📝 未来可期 <a class="header-anchor" href="#📝-未来可期" aria-label="Permalink to &quot;📝 未来可期&quot;">​</a></h2><blockquote><p>我们正在持续维护系统，并着手开发更多基础设施模块，按需一键安装，甚至提供开箱即用的各行业完整应用。</p></blockquote><p>项目 README 明确说明仍在持续维护，并规划按需安装的基础设施模块与行业应用。使用或关注项目时，建议以 Gitee 仓库的最新提交为准。</p><h2 id="💖-其他杂项" tabindex="-1">💖 其他杂项 <a class="header-anchor" href="#💖-其他杂项" aria-label="Permalink to &quot;💖 其他杂项&quot;">​</a></h2><blockquote><p>系统配置/控制台/个人资料管理等等、更多特性等你探索...</p></blockquote><p><code>src/config/index.ts</code> 中已包含系统标题、版本、主题、组件尺寸、语言、水印等默认设置；<code>utils/console.ts</code> 负责控制台输出；<code>views/login</code> 提供登录页。其余模块欢迎在仓库中自行探索。</p>',26)])])}const b=t(a,[["render",r]]);export{h as __pageData,b as default};
